from pathlib import Path
S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
n={'策略方向':'初進及重進固定做多或做空；不因日型態自動切方向。','進場時間':'普通初進HHmm，條件允許可改提早；前根<目標<=本根觸發，前根時刻回退減2400。','出場時間':'每次初進時刻重設my出場時間為此值；到計畫時間跨越會清已進計數，未延後則open平，並繼續後續分支。','相對昨收':'需要才限制交易日首open−保存期貨昨收在開盤上下界，皆可不查；不是現貨昨收比較。','開盤最高':'開盤−期貨昨收點數上界，含等號，只在相對昨收需要時篩普通初進。','開盤最低':'同價差點數下界，含等號。','相對開盤時間':'TX可用交易日首期貨open、跨09:00首期貨open或當日現貨日資料open；非TX除皆可外都用交易日首open。','相對開盤要小於':'目前open−選定參考開盤點數上界，含等號，只篩普通初進。','相對開盤要大於':'相同價差點數下界，含等號。','進場相對MA':'普通初進需MA>0且目前open>=或<=均價；重進不重查。','計算MA時間':'昨日1345取商品IsCloseTime前close；今早0500取交易日切換前close（TWETF改收盤事件）；今早0845取交易日切換後open。','X日MA':'上述事件樣本含最新N筆平均，不足0擋啟用MA的普通初進。','價差條件':'保存交易日開盤−昨收現貨>=或<=價差點數，昨收現貨<=0不查；只篩普通初進。','價差點數':'開盤對昨收現貨的固定有號點數，非目前即時價差。','最多進場次數':'正N時已有進場且計數<N，空手回到上次進場價有利側即可再進，不重查初進濾網／時刻；0只關重進、不禁止初進。','停損停利':'使用才於持倉KBAR取樣執行直停、固定損、移停；不影響一般時間平與末筆。','停損比':'每次進場價加減%或點數固定線，open觸損退出但保留已進計數，供再進。','啟動移停比':'每次建／再進價加減有利距離，取樣open到達才推追蹤線。','移停拉回比':'以當根open換%或點數，線只向有利方向；移停退出會把已進清0。','直接停利比':'取樣open第一順位到有利距離即退並清已進，不需先有移停。','提早進場':'開盤−昨收落提早上下界就改時刻，普通初進其他條件仍要過。','開盤小於可提早':'開盤−昨收可提早的點數上界，含等號。','開盤大於可提早':'同價差下界，含等號。','提早進場時間':'條件成立取代普通時刻；若隔夜型提早時間早於目前延後退出，會上調到目前退出時間。','延後出場':'獲利逐次加分鐘；開低或日盤合計可改今日時刻／設0停時間平；組合任一0則0，否則取較晚。比開盤高／價格相對昨收兩enum未有實作分支。','獲利以上延後':'獲利延後模式，時間跨越時open相對當前進場價乘方向的點數利潤>=門檻才延，不扣成本判。','每次延X分':'獲利延後每次以AddMinute加此實際分鐘，超最後出場時間截到最後時刻。','最後出場時間':'獲利模式只在下一根時間<=此值時可再延，並截計畫出場到此值。','開盤小於可延後':'開低延後／組合模式，開盤−期貨昨收的點數上界，含等號。','開盤大於可延後':'同價差下界，含等號。','出場延後日期':'今日改用出場延後時間；明日實際把my出場時間設0，不是預約次日此時間，條件每日再算。','出場延後時間':'開低條件成立且日期今日時替代原時刻；明日不讀此欄。','日盤合計天數':'交易日切換累積前保存日收−前日開盤，樣本數嚴格>N後才算最近N筆合計，非N日收盤報酬。','合計小於可延後':'最近日盤點數合計的延後上界，含等號。','合計大於可延後':'相同合計的下界，含等號。','合計延後日期':'合計條件成立，今日改合計延後時間、明日設0停時間平；組合與開低結果任一0即0。','合計延後時間':'合計模式且今日時用此HHmm；和開低組合兩者非0時取較晚。','KBAR間隔ex':'只篩持倉價格風控；前置重進、初進、計畫時間平與延後計算都不必合相位。','開始交易時間':'價格風控ValidKBAR相位原點，不是前置重進的最早時間。'}
add('時間當沖_多次進場','時間與開盤／MA條件先建立一口，固定停損後回價可多次再進；退出可按獲利、開低與多日日盤點數延後。','時間交易與停損重進',['普通初進跨所選提早／正常時刻，通過開盤相對昨收、進場相對開盤、MA及開盤對昨收現貨條件，open進一口。','每根最前先檢已有進場且計數未滿的空手：多open>=上次進場價、空<=即可再進，完全不重查時刻與初進濾網；新進計數加一。'],['計畫出場時間每次可依開低／日盤合計改今日時刻或0；獲利延後於跨越時達利潤門檻才逐次加分鐘至最後時刻。','計畫時間跨越先清已進，未延後便open平，但不return，因此同根仍可再跑風控或初進。前置重進甚至能先進後在本根時間平。','持倉KBAR且風控啟用時，open按直停→固定損→已有移停→推線。直停／移停清已進，固定損保留，才容許後續回價再進。','換約前當根open平且清已進，末筆close平。末後會刪相鄰同時間、等量反向交易並加回滑價、減交易次數。'],[cost,'交易日開盤在IsSameDate切換重設，TX09:00參考用前根<09:00<=本根取價；現貨09:00選當日日資料open，不必精確分鐘現貨。','明日延後的實作是my出場時間=0而停用時間平，直到後續重新計畫；不是向市場預約次日固定時間。日盤合計需樣本數>N才開始。'],['重進可能在原本出場時刻之外、也可同根先進再平；最多進場次數只是此計數週期，不是全回測交易次數或同時口數。','同時間合併只查反向量，不查價格相同，刪紀錄後僅調交易次數與累計績效，沒有重算GrossProfit／Loss／DD等全部統計；紀錄與部分指標可能不再一致。','my出場時間為私有欄位且Clear未重設，依初進或模式才賦值；比開盤高／價格相對昨收延後enum沒有分支實作，不能套名稱推論。','初段未先遇交易日切換時日開盤與相對開盤參考可為0；缺資料會影響濾網，風控也只看open而非盤中high／low。'],n)
out['SuperDaily/Stg時間當沖_多次進場']['caveats'].append('MergeTrade倒序刪除兩筆後只將迴圈索引減一，未依縮短清單重設；例如原3筆刪掉末兩筆，下一輪讀索引1但Count只剩1，會越界中斷。')
(S/'analysis/SuperDaily.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
p=S/'programs.json';programs=json.loads(p.read_text('utf-8-sig'));programs['SuperDaily']='以期貨分鐘／逐筆資料整合期現價差、外資及選擇權籌碼、開盤與多日反轉、固定時刻和委量異常交易。H系列各自決定取樣、中線、反手與跨日；時間系列涵蓋重進、獲利續抱及日夜配置。每個策略實例的子項共享FIFO績效，非獨立帳本；成交取open／close／線價、曆日或交易日、換約與末端是否真平均按各版實碼分別說明。';p.write_text(json.dumps(programs,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print('Wrote final Daily multi-entry/overview')
